    projectDescription(description: Description): Box {
        const element: Description = description
        const ph = "<description>"
        return new MultiLineTextBox2(
            element,
            "study-part-description",
            () => {
                return element.text
            },
            (t: string) => {
                element.text = t
            },
            { placeHolder: ph, cssClass: "desc" },
        )
    }

